MATCH (p:Player), (t:Team)
WHERE p.current_team = t.team_name
  AND EXISTS { MATCH (p)-[:MentionedIn]->(:Document) }
  AND EXISTS { MATCH (t)-[:MentionedIn]->(:Document) }
  AND (
    (CAST(p.fiba_world_cup AS INT64) < 0 AND CAST(p.mvp_awards AS INT64) <= 0)
    OR
    (
      (
        date_part('year', strptime(p.birth_date, '%Y/%m/%d')) > 1948
        OR (
          date_part('year', strptime(p.birth_date, '%Y/%m/%d')) = 1948
          AND (
            date_part('month', strptime(p.birth_date, '%Y/%m/%d')) > 10
            OR (
              date_part('month', strptime(p.birth_date, '%Y/%m/%d')) = 10
              AND date_part('day', strptime(p.birth_date, '%Y/%m/%d')) > 14
            )
          )
        )
      )
      AND CAST(p.fiba_world_cup AS INT64) >= 0
    )
  )
WITH t.team_name AS team_name, MIN(CAST(p.fiba_world_cup AS INT64)) AS min_fiba
RETURN team_name AS col1, min_fiba AS col2

